mapper.sql:
FROM telemetry_parameter p INNER JOIN selected_params s ON p.telemetry_code = s.telemetry_code AND p.source_type = s.source_type AND (s.source_identity IS NULL OR p.source_identity = s.source_identity)
p.task_id = #{taskId,jdbcType=VARCHAR} 1 = 0
AND p.telemetry_type = #{telemetryType,jdbcType=VARCHAR}

mapper.select:
, ranked_data AS ( SELECT s.selection_index, p.telemetry_name, p.value_type, p.`value`, p.value_text, p.state_name, p.state_type, p.processed_at, ROW_NUMBER() OVER ( PARTITION BY s.selection_index ORDER BY p.source_time DESC, p.source_identity ASC, p.telemetry_type ASC ) AS row_num
)
SELECT selection_index, telemetry_name, value_type, `value`, value_text, state_name, state_type, processed_at FROM ranked_data WHERE row_num = 1 ORDER BY selection_index ASC
